/bin/zsh -lc "nl -ba analysis.py | sed -n '1,220p'; python -c \"import numpy as np,pandas as pd; from analysis import fit_ses_effect
cases=[('constant outcome',pd.DataFrame({'SES':[0.,1.,2.],'BA DEGREE COMPLETED':[0,0,0]})),('constant SES',pd.DataFrame({'SES':[1.,1.,1.,1.],'BA DEGREE COMPLETED':[0,1,0,1]})),('missing',pd.DataFrame({'SES':[0.,np.nan],'BA DEGREE COMPLETED':[0,1]}))]
for name,d in cases:
 try: print(name,fit_ses_effect(d))
 except Exception as e: print(name,type(e).__name__,str(e))\""

